-- =============================================================================
-- 20260525120000_vulnerability_pentest.sql
-- =============================================================================

-- Vulnerability scanner findings + penetration test engagement tracking.

create table if not exists public.vulnerability_findings (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  scanner text not null check (scanner in ('qualys', 'tenable', 'other')),
  external_id text not null,
  title text not null,
  severity text not null default 'medium'
    check (severity in ('low', 'medium', 'high', 'critical')),
  cvss_score numeric(4,1),
  asset_host text,
  cve_id text,
  status text not null default 'open'
    check (status in ('open', 'in_progress', 'resolved', 'risk_accepted')),
  incident_id uuid references public.incidents (id) on delete set null,
  raw_payload jsonb,
  detected_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, scanner, external_id)
);

create index if not exists vulnerability_findings_user_status_detected_idx
  on public.vulnerability_findings (user_id, status, detected_at desc);

create index if not exists vulnerability_findings_user_severity_idx
  on public.vulnerability_findings (user_id, severity, detected_at desc);

alter table public.vulnerability_findings enable row level security;

create policy "vulnerability_findings_select_own"
  on public.vulnerability_findings for select
  using (auth.uid() = user_id);

create policy "vulnerability_findings_insert_own"
  on public.vulnerability_findings for insert
  with check (auth.uid() = user_id);

create policy "vulnerability_findings_update_own"
  on public.vulnerability_findings for update
  using (auth.uid() = user_id);

drop trigger if exists vulnerability_findings_set_updated_at on public.vulnerability_findings;
create trigger vulnerability_findings_set_updated_at
  before update on public.vulnerability_findings
  for each row
  execute procedure public.set_updated_at();

create table if not exists public.pen_test_engagements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  name text not null,
  scope_summary text not null,
  status text not null default 'planned'
    check (status in ('planned', 'active', 'completed', 'cancelled')),
  starts_at timestamptz,
  ends_at timestamptz,
  lead_hint text,
  findings_count integer not null default 0 check (findings_count >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists pen_test_engagements_user_status_start_idx
  on public.pen_test_engagements (user_id, status, starts_at desc nulls last);

alter table public.pen_test_engagements enable row level security;

create policy "pen_test_engagements_select_own"
  on public.pen_test_engagements for select
  using (auth.uid() = user_id);

create policy "pen_test_engagements_insert_own"
  on public.pen_test_engagements for insert
  with check (auth.uid() = user_id);

create policy "pen_test_engagements_update_own"
  on public.pen_test_engagements for update
  using (auth.uid() = user_id);

create policy "pen_test_engagements_delete_own"
  on public.pen_test_engagements for delete
  using (auth.uid() = user_id);

drop trigger if exists pen_test_engagements_set_updated_at on public.pen_test_engagements;
create trigger pen_test_engagements_set_updated_at
  before update on public.pen_test_engagements
  for each row
  execute procedure public.set_updated_at();

-- =============================================================================
-- 20260526120000_org_rbac.sql
-- =============================================================================

-- Organization-scoped RBAC: shared workspaces, delegated approvers, security reviewer roles.
-- Apply after platform_spine. Backward compatible: rows with org_id null keep per-user RLS.

create table if not exists public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  created_by uuid not null references public.profiles (id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists organizations_created_by_idx
  on public.organizations (created_by, created_at desc);

alter table public.organizations enable row level security;

create table if not exists public.organization_members (
  org_id uuid not null references public.organizations (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  role text not null check (role in (
    'owner', 'admin', 'operator', 'approver', 'security_reviewer', 'viewer'
  )),
  created_at timestamptz not null default now(),
  primary key (org_id, user_id)
);

create index if not exists organization_members_user_idx
  on public.organization_members (user_id, org_id);

alter table public.organization_members enable row level security;

-- ---------------------------------------------------------------------------
-- RLS helpers
-- ---------------------------------------------------------------------------
create or replace function public.is_org_member(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.organization_members m
    where m.org_id = p_org_id and m.user_id = auth.uid()
  );
$$;

create or replace function public.has_org_role(p_org_id uuid, p_roles text[])
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.organization_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = any (p_roles)
  );
$$;

grant execute on function public.is_org_member(uuid) to authenticated;
grant execute on function public.has_org_role(uuid, text[]) to authenticated;

-- ---------------------------------------------------------------------------
-- Organizations + members policies
-- ---------------------------------------------------------------------------
create policy "organizations_select_member"
  on public.organizations for select
  using (public.is_org_member(id));

create policy "organizations_insert_creator"
  on public.organizations for insert
  with check (created_by = auth.uid());

create policy "organizations_update_admin"
  on public.organizations for update
  using (public.has_org_role(id, array['owner', 'admin']));

create policy "organization_members_select_member"
  on public.organization_members for select
  using (public.is_org_member(org_id));

create policy "organization_members_insert_admin"
  on public.organization_members for insert
  with check (public.has_org_role(org_id, array['owner', 'admin']));

create policy "organization_members_update_admin"
  on public.organization_members for update
  using (public.has_org_role(org_id, array['owner', 'admin']));

create policy "organization_members_delete_admin"
  on public.organization_members for delete
  using (
    public.has_org_role(org_id, array['owner', 'admin'])
    and role <> 'owner'
  );

drop trigger if exists organizations_set_updated_at on public.organizations;
create trigger organizations_set_updated_at
  before update on public.organizations
  for each row
  execute procedure public.set_updated_at();

-- Bootstrap org + owner membership (security definer)
create or replace function public.create_organization_for_user(p_name text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id uuid;
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;
  insert into public.organizations (name, created_by)
  values (left(trim(p_name), 200), v_uid)
  returning id into v_org_id;

  insert into public.organization_members (org_id, user_id, role)
  values (v_org_id, v_uid, 'owner');

  return v_org_id;
end;
$$;

grant execute on function public.create_organization_for_user(text) to authenticated;

