      select 1 from public.remediation_runs r
      where r.id = remediation_run_steps.remediation_run_id
      and (
        r.user_id = auth.uid()
        or (r.org_id is not null and public.has_org_role(r.org_id, array['owner', 'admin', 'operator']))
      )
    )
  );

